window.MAPD=window.MAPD||{};
// Lazy per-map blob: only the default map's window.MAPD entry is inlined; every other map's
// assets/mapd/<slug>.js is loaded on first open via a <script> tag (NOT fetch, so it works over
// file://). The .js self-assigns window.MAPD[slug]; ensureMapd's onload just fires the queued
// callbacks. Concurrent opens of the same map dedupe through _mapdq; onerror drains the queue too,
// so a missing blob falls back to the map-empty state (_md returns null). The whole-roster
// iterations (drawGmBand/updateMapTabs) read the always-inlined window.MAPIDX index instead, so
// they never need an unloaded blob.
//
// Row layout (size reduction, mirrors report.py's _MAP_HERO_FIELDS/_MAP_PLAYER_FIELDS/
// _MAP_DRILL_FIELDS): heroes/players/drill.rows are positional arrays, not {statKey:value}
// dicts -- this key set is fixed across EVERY map/mode (unlike PRSEASON's per-hero-config stat
// set), so the index layout is hardcoded here rather than transmitted. heroes, players AND drill
// rows deliberately share their first 11 slots so _statcells() below (or any future drill-panel
// reader) can read any of the three shapes unchanged. Drill rows' swr (index 10, same as
// heroes/players) is RANKING-only -- report.py's map_cards_block sorts the player-page best/worst
// map cards by it, never prints it; drawDrill below still prints raw wr as the headline.
//   heroes:      [m,w,wr,hrs,k,d,a,h,dmg,dt,swr,hx]
//   players:     [m,w,wr,hrs,k,d,a,h,dmg,dt,swr,pi]
//   drill rows:  [m,w,wr,hrs,k,d,a,h,dmg,dt,swr]
// hx/pi (string interning, ledger 2026-07-25 #88): a hero's (slug,name,role) triple and a player's
// name repeat across every map x mode x drill entry, so each row carries a small page-wide int
// instead of the strings themselves -- window._MAPDHX[hx]=[slug,name,role], _MAPDPX[pi]=name
// (report.py's _mapd_hero_idx_js/_mapd_player_idx_js, emitted once alongside window.MAPIDX). The
// drill object's own keys are 'pi' indices too (not raw igns), and a drill entry's `rows` are keyed
// by 'hx' index -- except '_all', which is the player's whole-map summary row and isn't a hero at
// all, so it rides through as the literal string every drill entry already used for it.
var MI_M=0,MI_W=1,MI_WR=2,MI_HRS=3,MI_K=4,MI_D=5,MI_A=6,MI_H=7,MI_DMG=8,MI_DT=9,MI_SWR=10;
var MH_HX=11,MP_PI=11;
function _mhx(i){return (window._MAPDHX&&window._MAPDHX[i])||['','',''];}
function _mpx(i){return (window._MAPDPX&&window._MAPDPX[i])||'';}
var _mapdq={};
function ensureMapd(slug,cb){
 if(window.MAPD[slug]){if(cb)cb();return;}
 if(_mapdq[slug]){if(cb)_mapdq[slug].push(cb);return;}_mapdq[slug]=cb?[cb]:[];
 var drain=function(){var q=_mapdq[slug]||[];_mapdq[slug]=null;for(var i=0;i<q.length;i++){if(q[i])q[i]();}};
 var s=document.createElement('script');s.src=(window.ASSET_BASE||'')+'assets/mapd/'+slug+'.js';
 s.onload=drain;s.onerror=drain;document.head.appendChild(s);
}
var MGOOD=(window.RIVALS_TOK&&window.RIVALS_TOK.good)||'#7CE7B0';
function _mesc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function _mnum(n){return Math.round(n).toLocaleString();}
function _mapMode(){return document.getElementById('maps-mode').getAttribute('data-mmode')||'qm';}
function _modeLabel(){return {qm:'Quick Match',comp:'Competitive'}[_mapMode()];}
