 document.getElementById('mappanel-'+slug).classList.toggle('map-empty',!md);
 if(!md){box.innerHTML="<h2 class='hero-title'>"+_mesc(nm)+"</h2><p class='sub'>No "+_modeLabel()+" games recorded on this map.</p>";return;}
 var bh=_mfirst(md.heroes),bp=_mfirst(md.players.all),mph=null;
 for(var i=0;i<md.heroes.length;i++){if(!mph||md.heroes[i][MI_M]>mph[MI_M])mph=md.heroes[i];}
