  // affordance in the card styled with a plain solid underline instead of the dotted .chelp/.tmtip
  // convention every other hoverable/expandable bit of this card uses -- give it the same classes
  // (report.css's .tmd-ss-more keeps its own button reset + a pointer cursor for the real click).
  var moreBtn=cut>0
    ?"<button class='tmd-ss-more chelp tmtip' onclick='_tmdSeasonsMore(this)' title='Show "+cut
      +" earlier season"+(cut===1?'':'s')+"'>+"+cut+" earlier season"
      +(cut===1?'':'s')+"</button> ":'';
  var strip="<p class='drv tmd-note tmd-seasons-strip'>By season: "+moreBtn+old+recent.join(' · ')+"</p>";
  return (head?"<p class='sec-note tmd-note tmd-seasons'>"+head+"</p>":'')+strip;
