// Row click = expand (2026-07-23 redesign): the group-table row (.tmgrow) is a plain container,
// not a button, so its player names can be real #p- profile <a> links. One delegated listener
// (not one per row -- ~1,400 groups) treats a click ANYWHERE on the row EXCEPT a link or the
// caret button itself (whose own onclick already calls tmToggle) as an expand-row click, so
// clicking blank row space still expands with the mouse while clicking a name goes straight to
// that player's profile instead. Mirrors the capture-phase delegation pattern used below for
// closing the drilldown on an outer sort/filter -- bubble phase here since nothing needs to run
// before the native link navigation.
document.addEventListener('click',function(e){
  var row=e.target.closest&&e.target.closest('.tmgrow');
  if(!row||!row.closest('#teammates-mode'))return;
  if(e.target.closest('a'))return;                 // real profile link -- let it navigate
  if(e.target.closest('button.tmcaret'))return;     // caret's own onclick already fired tmToggle
  var btn=row.querySelector('button.tmcaret');
  if(btn)tmToggle(btn);
});
// Close before anything that reorders or hides rows: OUTER-table header sorts + the filter
// boxes (the group tables' AND the pairings table's — both host injected tm-detail rows).
// Capture phase runs BEFORE the th's inline onclick, so the detail row is gone by sort time.
// Headers INSIDE a drilldown (they live under the same wrapper) must NOT close it —
// sorting the card's own table collapsed the card (owner-reported).
document.addEventListener('click',function(e){var t=e.target;
  if(!t||!t.closest)return;
  var th=t.closest('th.srt');
  if(th&&!th.closest('tr.tm-detail')&&th.closest('.tm-table,#tm-pairs-box'))_tmCloseAll();},true);
