// synthesizes a click — without this, a keyboard sort with a card open threw in sortTable
document.addEventListener('keydown',function(e){
  if(e.key!=='Enter'&&e.key!==' ')return;
  var t=e.target;if(!t||!t.closest)return;
  var th=t.closest('th.srt');
  if(th&&!th.closest('tr.tm-detail')&&th.closest('.tm-table,#tm-pairs-box'))_tmCloseAll();},true);
document.addEventListener('input',function(e){var t=e.target;
  if(t&&(t.id==='tm-filter'||t.id==='tm-pairs-filter'))_tmCloseAll();},true);
